import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p7_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor small_k_matmul_cuda(torch::Tensor a, torch::Tensor b);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("small_k_matmul", &small_k_matmul_cuda, "Small-K matmul CUDA");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tiled GEMM kernel specialized for small K (K=64).
// Each thread block covers BM rows and BN columns.
// Each thread computes TM rows x TN columns of output.
// We stage A and B tiles in shared memory for reuse.

#define BM 64
#define BN 64
#define BK 64
#define TM 4
#define TN 4
#define THREADS_M (BM / TM)  // 16
#define THREADS_N (BN / TN)  // 16

__global__ void small_k_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    // Block tile origin
    int block_row = blockIdx.y * BM;
    int block_col = blockIdx.x * BN;

    // Thread index within block
    int tid = threadIdx.x;
    int thread_row = tid / THREADS_N;  // 0..15
    int thread_col = tid % THREADS_N;  // 0..15

    // Shared memory for A tile (BM x BK) and B tile (BK x BN)
    __shared__ float sA[BM][BK];
    __shared__ float sB[BK][BN];

    // Accumulators
    float acc[TM][TN] = {};

    // Total threads per block = THREADS_M * THREADS_N = 256
    int total_threads = THREADS_M * THREADS_N;

    // Load A tile: BM*BK = 64*64 = 4096 elements, 256 threads -> 16 each
    int a_elems = BM * BK;
    for (int i = tid; i < a_elems; i += total_threads) {
        int r = i / BK;
        int c = i % BK;
        int global_r = block_row + r;
        int global_c = c;  // K tile starts at 0 (K=64, single tile)
        sA[r][c] = (global_r < M && global_c < K) ? A[global_r * K + global_c] : 0.0f;
    }

    // Load B tile: BK*BN = 64*64 = 4096 elements, 256 threads -> 16 each
    int b_elems = BK * BN;
    for (int i = tid; i < b_elems; i += total_threads) {
        int r = i / BN;
        int c = i % BN;
        int global_r = r;  // K tile starts at 0
        int global_c = block_col + c;
        sB[r][c] = (global_r < K && global_c < N) ? B[global_r * N + global_c] : 0.0f;
    }

    __syncthreads();

    // Compute TM x TN output fragment
    #pragma unroll
    for (int k = 0; k < BK; k++) {
        float a_vals[TM];
        float b_vals[TN];
        #pragma unroll
        for (int m = 0; m < TM; m++) {
            a_vals[m] = sA[thread_row * TM + m][k];
        }
        #pragma unroll
        for (int n = 0; n < TN; n++) {
            b_vals[n] = sB[k][thread_col * TN + n];
        }
        #pragma unroll
        for (int m = 0; m < TM; m++) {
            #pragma unroll
            for (int n = 0; n < TN; n++) {
                acc[m][n] += a_vals[m] * b_vals[n];
            }
        }
    }

    // Write results
    #pragma unroll
    for (int m = 0; m < TM; m++) {
        int global_r = block_row + thread_row * TM + m;
        if (global_r >= M) continue;
        #pragma unroll
        for (int n = 0; n < TN; n++) {
            int global_c = block_col + thread_col * TN + n;
            if (global_c < N) {
                C[global_r * N + global_c] = acc[m][n];
            }
        }
    }
}

torch::Tensor small_k_matmul_cuda(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda() && b.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(a.dtype() == torch::kFloat32 && b.dtype() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(a.is_contiguous() && b.is_contiguous(), "Inputs must be contiguous");

    int M = a.size(0);
    int K = a.size(1);
    int N = b.size(1);

    TORCH_CHECK(K == 64 && b.size(0) == 64, "K must be 64");

    auto out = torch::empty({M, N}, a.options());

    dim3 block(THREADS_M * THREADS_N);  // 256 threads
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);

    small_k_matmul_kernel<<<grid, block>>>(
        a.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        M, N, K
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a single matrix multiplication (C = A * B) with a small K dimension
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs matrix multiplication.

                Args:
                    A: Input tensor of shape (M, K).
                    B: Input tensor of shape (K, N).

                Returns:
                    Output tensor of shape (M, N).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if (A.is_cuda and B.is_cuda and
                A.dtype == torch.float32 and B.dtype == torch.float32 and
                A.dim() == 2 and B.dim() == 2 and
                A.is_contiguous() and B.is_contiguous() and
                A.shape[1] == 64 and B.shape[0] == 64):
            return _stark_get_extension().small_k_matmul(A, B)
        return torch.matmul(A, B)
        # <<<END_IMPROVE>>>

