# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tiled GEMM kernel specialized for small K (K=64).
// Champion tile: BM=64, BN=64, BK=64, TM=4, TN=4, 256 threads/block.
// This version uses float4 vectorized loads for A and B tile staging.

#define BM 64
#define BN 64
#define BK 64
#define TM 4
#define TN 4
#define THREADS_M (BM / TM)  // 16
#define THREADS_N (BN / TN)  // 16
#define BLOCK_THREADS (THREADS_M * THREADS_N)  // 256

__global__ void small_k_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N
) {
    int block_row = blockIdx.y * BM;
    int block_col = blockIdx.x * BN;

    int tid = threadIdx.x;
    int thread_row = tid / THREADS_N;
    int thread_col = tid % THREADS_N;

    __shared__ float sA[BM][BK];
    __shared__ float sB[BK][BN];

    float acc[TM][TN] = {};

    // Load A tile: BM*BK = 4096 floats, 256 threads -> 16 floats each = 4 float4 each
    // A is (M, 64) contiguous, so row stride = BK = 64.
    // Each thread loads 4 float4s (16 floats) from A.
    {
        // We assign each thread a linear index into the BM*BK tile.
        // 256 threads * 16 floats = 4096 = BM*BK. Exactly one pass.
        // Use float4: 256 threads * 4 float4s = 1024 float4s = 4096 floats.
        const float4* A4 = reinterpret_cast<const float4*>(A);
        float4* sA4 = reinterpret_cast<float4*>(&sA[0][0]);
        // BM*BK/4 = 1024 float4 elements; each thread handles 4.
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            int idx4 = tid + i * BLOCK_THREADS;  // 0..1023
            // idx4 maps to sA element [idx4*4 .. idx4*4+3]
            // sA row = (idx4*4) / BK, col/4 = (idx4*4 % BK) / 4
            int flat = idx4 * 4;  // flat index in BM*BK
            int r = flat / BK;
            int c4 = (flat % BK) / 4;  // float4 index along K
            int global_r = block_row + r;
            if (global_r < M) {
                sA4[r * (BK/4) + c4] = A4[global_r * (BK/4) + c4];
            } else {
                sA4[r * (BK/4) + c4] = make_float4(0.f, 0.f, 0.f, 0.f);
            }
        }
    }

    // Load B tile: BK*BN = 4096 floats, 256 threads -> 16 floats each = 4 float4 each
    // B is (64, N) contiguous, row stride = N.
    // We load BK rows, each BN=64 contiguous floats from B.
    // For interior blocks (block_col + BN <= N), use float4.
    {
        // BK*BN/4 = 1024 float4 elements; each thread handles 4.
        bool full_n = (block_col + BN <= N);
        if (full_n) {
            const float4* B4 = reinterpret_cast<const float4*>(B);
            float4* sB4 = reinterpret_cast<float4*>(&sB[0][0]);
            #pragma unroll
            for (int i = 0; i < 4; i++) {
                int idx4 = tid + i * BLOCK_THREADS;
                int flat = idx4 * 4;
                int r = flat / BN;
                int c4 = (flat % BN) / 4;
                int global_c4 = block_col / 4 + c4;  // block_col is multiple of BN=64, so aligned
                sB4[r * (BN/4) + c4] = B4[r * (N/4) + global_c4];
            }
        } else {
            // Scalar fallback for boundary N block
            int b_elems = BK * BN;
            for (int i = tid; i < b_elems; i += BLOCK_THREADS) {
                int r = i / BN;
                int c = i % BN;
                int global_c = block_col + c;
                sB[r][c] = (global_c < N) ? B[r * N + global_c] : 0.0f;
            }
        }
    }

    __syncthreads();

    // Compute TM x TN output fragment
    #pragma unroll
    for (int k = 0; k < BK; k++) {
        float a_vals[TM];
        float b_vals[TN];
        #pragma unroll
        for (int m = 0; m < TM; m++) {
            a_vals[m] = sA[thread_row * TM + m][k];
        }
        #pragma unroll
        for (int n = 0; n < TN; n++) {
            b_vals[n] = sB[k][thread_col * TN + n];
        }
        #pragma unroll
        for (int m = 0; m < TM; m++) {
            #pragma unroll
            for (int n = 0; n < TN; n++) {
                acc[m][n] += a_vals[m] * b_vals[n];
            }
        }
    }

    // Write results
